      },
      {
        "code": "RTM_SELECTION",
        "text": "Movers are a selected subset of players; results may not generalise to shapers who do not switch teams."
      },
      {
        "code": "MULTIPLE_TESTING",
        "text": "If multiple thresholds or alternative subtyping rules are explored post-hoc, false positive probability increases."
      }
    ],
    "predicted_outcome": {
      "supported": 0.05,
      "rejected": 0.2,
      "untestable": 0.1,
      "artifact": 0.05,
      "uncertain": 0.6
    },
